def get_html_template(api_key: str, styles: str, javascript: str) -> str:
    """Generate the main HTML template structure."""
    return f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Multi-Database Query Agent</title>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/marked/4.3.0/marked.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.8.0/highlight.min.js"></script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.8.0/styles/github.min.css">
    <style>
        {styles}
        .theme-toggle-btn {{
            background: var(--theme-toggle-bg, #f0f0f0);
            color: var(--theme-toggle-color, #222);
            border: 1px solid var(--theme-toggle-border, #ccc);
            border-radius: 4px;
            padding: 6px 14px;
            font-size: 16px;
            cursor: pointer;
            margin-left: 16px;
            transition: background 0.2s, color 0.2s;
        }}
        body.dark-theme .theme-toggle-btn {{
            background: var(--theme-toggle-bg-dark, #222);
            color: var(--theme-toggle-color-dark, #f0f0f0);
            border-color: var(--theme-toggle-border-dark, #444);
        }}
        /* Ensure result panels and syntax highlighting use theme variables */
        .result-panel {{
            background: var(--result-panel-bg, #f8f9fa);
            color: var(--result-panel-color, #222);
            border-radius: 8px;
            padding: 18px;
            margin: 20px 0;
            box-shadow: 0 2px 4px var(--result-panel-shadow, rgba(0,0,0,0.08));
            border: 1px solid var(--result-panel-border, #e1e5e9);
            font-size: 15px;
            overflow-x: auto;
        }}
        body.dark-theme .result-panel {{
            background: var(--result-panel-bg-dark, #23272e);
            color: var(--result-panel-color-dark, #f0f0f0);
            border-color: var(--result-panel-border-dark, #444);
            box-shadow: 0 2px 4px var(--result-panel-shadow-dark, rgba(0,0,0,0.32));
        }}
        /* Syntax highlighting container */
        pre, code {{
            font-family: 'Fira Mono', 'Menlo', 'Monaco', 'Consolas', monospace;
            font-size: 14px;
        }}
        pre.hljs, code.hljs {{
            background: var(--syntax-bg, #f8f9fa);
            color: var(--syntax-color, #222);
            border-radius: 6px;
            padding: 12px;
            border: 1px solid var(--syntax-border, #e1e5e9);
            overflow-x: auto;
        }}
        body.dark-theme pre.hljs, body.dark-theme code.hljs {{
            background: var(--syntax-bg-dark, #23272e);
            color: var(--syntax-color-dark, #f0f0f0);
            border-color: var(--syntax-border-dark, #444);
        }}
        /* Ensure inline code is legible in both themes */
        code:not(.hljs) {{
            background: var(--inline-code-bg, #f3f3f3);
            color: var(--inline-code-color, #222);
            border-radius: 4px;
            padding: 2px 6px;
            font-size: 13px;
        }}
        body.dark-theme code:not(.hljs) {{
            background: var(--inline-code-bg-dark, #23272e);
            color: var(--inline-code-color-dark, #f0f0f0);
        }}
    </style>
</head>
<body>
    <div class="header">
        <h1>🤖 Multi-Database Query Agent</h1>
        <p>Select a database and ask questions in natural language!</p>
        <button id="theme-toggle" class="theme-toggle-btn">🌙 Dark Mode</button>
    </div>

    <div class="database-selector">
        <h3>📊 Available Databases</h3>
        <div id="database-grid" class="database-grid">
            <!-- Databases will be loaded here -->
        </div>
        <button class="refresh-btn" onclick="loadDatabases()">🔄 Refresh Databases</button>
    </div>

    <div class="no-database-warning" id="no-database-warning">
        Please select a database first before asking questions.
    </div>

    <div class="tips-section">
        <h3>Query Guidelines</h3>
        <div class="tip-item">This system is read-only - ask questions to retrieve and analyze data</div>
        <div class="tip-item">Write operations (INSERT, UPDATE, DELETE) are not allowed</div>
        <div class="tip-item">Use phrases like "show me", "find", "count", "list", "get", "analyze"</div>
        <div class="tip-item">Be specific about what data you want to see</div>
    </div>

    <div class="examples">
        <h3>Try these examples:</h3>
        <div class="example-btn" onclick="setQuestion('Show me 5 records')">Show me 5 records</div>
        <div class="example-btn" onclick="setQuestion('What are the most common categories?')">What are the most common categories?</div>
        <div class="example-btn" onclick="setQuestion('Count records by type')">Count records by type</div>
        <div class="example-btn" onclick="setQuestion('Find records from 2020')">Find records from 2020</div>
    </div>

    <div class="input-section">
        <div class="selected-db-indicator" id="selected-db-indicator">
            <strong>Selected Database:</strong>
            <span id="selected-db-name"></span>
            <span id="selected-db-type"></span>
        </div>
        <div class="input-row">
            <input type="text" id="question" placeholder="Select a database first, then ask a question..." disabled />
            <button id="ask-btn" onclick="askQuestion()" disabled>Ask</button>
        </div>
    </div>

    <div id="chat" class="chat"></div>

    <script>
        // Theme toggle logic
        (function() {{
            const body = document.body;
            const themeToggleBtn = document.getElementById('theme-toggle');
            // Helper to set theme
            function applyTheme(theme) {{
                if (theme === 'dark') {{
                    body.classList.add('dark-theme');
                    themeToggleBtn.textContent = '☀️ Light Mode';
                }} else {{
                    body.classList.remove('dark-theme');
                    themeToggleBtn.textContent = '🌙 Dark Mode';
                }}
            }}
            // Get theme from localStorage or default to light
            let theme = localStorage.getItem('theme');
            if (!theme) {{
                theme = 'light';
            }}
            applyTheme(theme);

            themeToggleBtn.addEventListener('click', function() {{
                theme = (theme === 'dark') ? 'light' : 'dark';
                localStorage.setItem('theme', theme);
                applyTheme(theme);
            }});
        }})();
    </script>
    <script>
        {javascript}
    </script>
</body>
</html>"""
